const Log = require("./log.js");

const VALID_HOOKS = [
    // Message Routing Path
   "onSend",
   "preRoute",
   "preDeliver",
   "postDeliver",
   "onReceive",
   "postReceive",
   "onComplete",
   // Module install hooks
   "preInstall",
   "postInstall",
   "preUninstall",
   "postUninstall",
   // Runtime life cycle hooks (Z-08)
   "preShutdown",
   // Reload of the flows after a change in storage (Z-09)
   "preReload",
   // Deploy pipeline (Z-06): called by the runtime through handlers(), not through
   // trigger() - see runtime/lib/flows/deployHooks.js
   "preDeploy",
   "postDeploy"
]

// #76: the message of the error of trigger() for a rejection value that cannot be
// converted to a string (not translated, the same text as in the runtime)
const NOT_PRINTABLE = "(the value cannot be printed)";

// Flags for what hooks have handlers registered
let states = { }

// Doubly-LinkedList of hooks by id.
// - hooks[id] points to head of list
// - each list item looks like:
//   {
//       cb: the callback function
//       label: the label of `name.label`, if any (Z-06)
//       handle: the frozen object that handlers() returns for this item (Z-06)
//       location: filename/line of code that added the hook
//       previousHook: reference to previous hook in list
//       nextHook: reference to next hook in list
//       removed: a flag that is set if the item was removed
//   }
let hooks = { }

// Hooks by label
let labelledHooks = { }

// Hook ids (`name.label`) registered from the `hooks` setting of settings.js
let settingsHookIds = [ ]

// Hooks that can be registered from the `hooks` setting (#7)
const SETTINGS_HOOKS = ["preReload", "preShutdown"];

/**
 * Runtime hooks engine
 *
 * The following hooks can be used:
 *
 * Message sending
 *  - `onSend` - passed an array of `SendEvent` objects. The messages inside these objects are exactly what the node has passed to `node.send` - meaning there could be duplicate references to the same message object.
 *  - `preRoute` - passed a `SendEvent`
 *  - `preDeliver` - passed a `SendEvent`. The local router has identified the node it is going to send to. At this point, the message has been cloned if needed.
 *  - `postDeliver` - passed a `SendEvent`. The message has been dispatched to be delivered asynchronously (unless the sync delivery flag is set, in which case it would be continue as synchronous delivery)
 *  - `onReceive` - passed a `ReceiveEvent` when a node is about to receive a message
 *  - `postReceive` - passed a `ReceiveEvent` when the message has been given to the node's `input` handler(s)
 *  - `onComplete` - passed a `CompleteEvent` when the node has completed with a message or logged an error
 *
 * @mixin @node-red/util_hooks
 */

/**
 * Register a handler to a named hook
 * @memberof @node-red/util_hooks
 * @param {String} hookId - the name of the hook to attach to
 * @param {Function} callback - the callback function for the hook
 */
function add(hookId, callback) {
    let [id, label] = hookId.split(".");
    if (VALID_HOOKS.indexOf(id) === -1) {
        throw new Error(`Invalid hook '${id}'`);
    }
    if (label && labelledHooks[label] && labelledHooks[label][id]) {
        throw new Error("Hook "+hookId+" already registered")
    }
    // Get location of calling code
    let callModule;
    const stack = new Error().stack;
    const stackEntries = stack.split("\n").slice(1);//drop 1st line (error message)
    const stackEntry2 = stackEntries[1];//get 2nd stack entry
    if (stackEntry2) {
        try {
            if (stackEntry2.indexOf(" (") >= 0) {
                callModule = stackEntry2.split("(")[1].slice(0, -1);
            } else {
                callModule = stackEntry2.split(" ").slice(-1)[0];
            }
        } catch (error) {
            Log.debug(`Unable to determined module when adding hook '${hookId}'. Stack:\n${stackEntries.join("\n")}`);
            callModule = "unknown:0:0";
        }
    } else {
        Log.debug(`Unable to determined module when adding hook '${hookId}'. Stack:\n${stackEntries.join("\n")}`);
        callModule = "unknown:0:0";
    }
    Log.debug(`Adding hook '${hookId}' from ${callModule}`);

    const hookItem = {cb:callback, label: label, location: callModule, previousHook: null, nextHook: null }
    // Z-06: the stable object that the runtime keeps per registration (handlers())
    hookItem.handle = Object.freeze({
        id: label ? id + "." + label : id,
        location: callModule,
        cb: callback,
        isRemoved: function() { return !!hookItem.removed }
    });

    let tailItem = hooks[id];
    if (tailItem === undefined) {
        hooks[id] = hookItem;
    } else {
        while(tailItem.nextHook !== null) {
            tailItem = tailItem.nextHook
        }
        tailItem.nextHook = hookItem;
        hookItem.previousHook = tailItem;
    }

    if (label) {
        labelledHooks[label] = labelledHooks[label]||{};
        labelledHooks[label][id] = hookItem;
    }

    // TODO: get rid of this;
    states[id] = true;
}

/**
 * Remove a handled from a named hook
 * @memberof @node-red/util_hooks
 * @param {String} hookId - the name of the hook event to remove - must be `name.label`
 */
function remove(hookId) {
    let [id,label] = hookId.split(".");
    if ( !label) {
        throw new Error("Cannot remove hook without label: "+hookId)
    }
    Log.debug(`Removing hook '${hookId}'`);
    if (labelledHooks[label]) {
        if (id === "*") {
            // Remove all hooks for this label
            let hookList = Object.keys(labelledHooks[label]);
            for (let i=0;i<hookList.length;i++) {
                removeHook(hookList[i],labelledHooks[label][hookList[i]])
            }
            delete labelledHooks[label];
        } else if (labelledHooks[label][id]) {
            removeHook(id,labelledHooks[label][id])
            delete labelledHooks[label][id];
            if (Object.keys(labelledHooks[label]).length === 0){
                delete labelledHooks[label];
            }
        }
    }
}

function removeHook(id,hookItem) {
    let previousHook = hookItem.previousHook;
    let nextHook = hookItem.nextHook;

    if (previousHook) {
        previousHook.nextHook = nextHook;
    } else {
        hooks[id] = nextHook;
    }
    if (nextHook) {
        nextHook.previousHook = previousHook;
    }
    hookItem.removed = true;
    if (!previousHook && !nextHook) {
        delete hooks[id];
        delete states[id];
    }
}


/**
 * The handlers registered for a hook, in the order of registration, without the removed ones
 * (Z-06). `trigger` and `invokeStack` do not use it; the deploy pipeline needs the handlers
 * one by one to give each a limit, an identity in logs and its own result (deployHooks.js).
 *
 * The object of a handler is the same for the life of the registration (a handler added again
 * under the same label is a new object), so a caller can key a WeakMap by it.
 *
 * The result is a snapshot: handlers added while the chain runs are not in it (unlike
 * `invokeStack`, which follows the list), and `isRemoved()` tells whether a handler of the
 * snapshot was removed by `remove` in the meantime. `clear()` does not mark the handlers
 * as removed.
 *
 * Exposed as a non-enumerable, read-only and not configurable property `hooks.handlers`, outside the contract of
 * `RED.hooks`.
 * @private
 * @param {String} hookId - the hook name without a label
 * @return {Array<{id: String, location: String, cb: Function, isRemoved: Function}>}
 */
function handlers(hookId) {
    const list = [];
    let hookItem = hooks[hookId];
    while (hookItem) {
        if (!hookItem.removed) {
            list.push(hookItem.handle);
        }
        hookItem = hookItem.nextHook;
    }
    return list;
}

function trigger(hookId, payload, done) {
    let hookItem = hooks[hookId];
    if (!hookItem) {
        if (done) {
            done();
            return;
        } else {
            return Promise.resolve();
        }
    }
    if (!done) {
        return new Promise((resolve,reject) => {
            invokeStack(hookItem,payload,function(err) {
                if (err !== undefined && err !== false) {
                    if (!(err instanceof Error)) {
                        // #76: a value that cannot be converted to a string (an object without
                        // a prototype, a Proxy that throws) would make the conversion throw and
                        // the promise would never settle
                        try {
                            err = new Error(err);
                        } catch (e) {
                            err = new Error(NOT_PRINTABLE);
                        }
                    }
                    err.hook = hookId
                    reject(err);
                } else {
                    resolve(err);
                }
            })
        });
    } else {
        invokeStack(hookItem,payload,done)
    }
}
function invokeStack(hookItem,payload,done) {
    function callNextHook(err) {
        if (!hookItem || err) {
            done(err);
            return;
        }
        if (hookItem.removed) {
            hookItem = hookItem.nextHook;
            callNextHook();
            return;
        }
        const callback = hookItem.cb;
        if (callback.length === 1) {
            try {
                let result = callback(payload);
                if (result === false) {
                    // Halting the flow
                    done(false);
                    return
                }
                if (result && typeof result.then === 'function') {
                    result.then(handleResolve, handleReject)
                    return;
                }
                hookItem = hookItem.nextHook;
                callNextHook();
            } catch(err) {
                done(err);
                return;
            }
        } else {
            try {
                callback(payload,handleResolve)
            } catch(err) {
                done(err);
                return;
            }
        }
    }
    // A rejection always ends the chain (#61). `callNextHook` ends it only for a truthy
    // value, so a falsy reason (`Promise.reject()`, `throw undefined`, ...) would call the
    // same handler again without end.
    function handleReject(reason) {
        if (reason) {
            done(reason);
        } else {
            done(new Error(`Hook handler rejected without an error: ${typeof reason === "string" ? JSON.stringify(reason) : String(reason)}`));
        }
    }
    function handleResolve(result) {
        if (result === undefined) {
            hookItem = hookItem.nextHook;
            callNextHook();
        } else {
            done(result);
        }
    }
    callNextHook();
}

function settingsError(message) {
    const err = new Error(message);
    err.code = "invalid_hook_setting";
    return err;
}

/**
 * Remove the hooks registered by a previous call of `addFromSettings`
 * @memberof @node-red/util_hooks
 */
function removeFromSettings() {
    const ids = settingsHookIds;
    settingsHookIds = [];
    ids.forEach(hookId => remove(hookId));
}

/**
 * Register the hooks of the `hooks` setting of settings.js (#7):
 * `{ "preReload.<label>": fn, "preShutdown.<label>": fn }`. Only `preReload` and
 * `preShutdown` are allowed. The whole setting is validated before anything is
 * registered; on an error nothing changes. The hooks registered by a previous call
 * are removed first, so the call can be repeated.
 * @memberof @node-red/util_hooks
 * @param {Object} hooksSetting - hook id (`name.label`) to the hook function
 * @throws {Error} with `code: "invalid_hook_setting"` naming the offending key
 */
function addFromSettings(hooksSetting) {
    if (hooksSetting === null || typeof hooksSetting !== "object" || Array.isArray(hooksSetting)) {
        throw settingsError("Invalid 'hooks' setting: an object of hook functions is required");
    }
    const hookIds = Object.keys(hooksSetting);
    hookIds.forEach(hookId => {
        const separator = hookId.indexOf(".");
        const id = separator === -1 ? hookId : hookId.slice(0, separator);
        const label = separator === -1 ? "" : hookId.slice(separator + 1);
        if (SETTINGS_HOOKS.indexOf(id) === -1) {
            throw settingsError(`Invalid 'hooks' setting: '${hookId}' - only ${SETTINGS_HOOKS.join(" and ")} can be set, as <name>.<label>`);
        }
        if (label.trim() === "") {
            throw settingsError(`Invalid 'hooks' setting: '${hookId}' - the label is missing, use '${id}.<label>'`);
        }
        if (!/^[A-Za-z0-9_-]+$/.test(label) || label in Object.prototype) {
            throw settingsError(`Invalid 'hooks' setting: '${hookId}' - the label may contain only letters, digits, '_' and '-' and must not be a name of Object.prototype`);
        }
        if (typeof hooksSetting[hookId] !== "function") {
            throw settingsError(`Invalid 'hooks' setting: '${hookId}' - the value must be a function`);
        }
        if (has(hookId) && settingsHookIds.indexOf(hookId) === -1) {
            throw settingsError(`Invalid 'hooks' setting: '${hookId}' - a hook with this name and label is already registered`);
        }
    });
    removeFromSettings();
    hookIds.forEach(hookId => {
        add(hookId, hooksSetting[hookId]);
        settingsHookIds.push(hookId);
    });
}

function clear() {
    hooks = {}
    labelledHooks = {}
    states = {}
    settingsHookIds = []
}

function has(hookId) {
    let [id, label] = hookId.split(".");
    if (label) {
        return !!(labelledHooks[label] && labelledHooks[label][id])
    }
    return !!states[id]
}

module.exports = {
    has,
    clear,
    add,
    addFromSettings,
    removeFromSettings,
    remove,
    trigger
}

// Z-06: for the runtime only - not enumerable, so it does not show up as part of RED.hooks; read-only and not
// configurable (S-C3), so that a node cannot replace the accessor the deploy pipeline reads the handlers with
Object.defineProperty(module.exports, "handlers", {
    value: handlers,
    enumerable: false,
    writable: false,
    configurable: false
});
